      {"no":1,"patterns":["～{最中|さいちゅう}"],"meaning":"Đúng lúc đang… thì","structure":"Vている＋{最中|さいちゅう}","usage":"trong lúc đang làm gì thì có việc xảy ra, gây cản trở. Vế phía sau là một sự việc có tính bất ngờ xảy ra, gây cảm giác cản trở, làm phiền hành động đang thực hiện ở đằng trước.","examples":[{"jp":"スピーチの{最中|さいちゅう}に、{突然|とつぜん}{電気|でんき}が{消|き}えた","vi":"Đang phát biểu thì đột nhiên điện bị ngắt."}]},
      {"no":2,"patterns":["～ばかりだ","～{一方|いっぽう}だ"],"meaning":"Ngày càng…, cứ thế… (một chiều)","structure":"Vる＋ばかりだ\nVる＋{一方|いっぽう}だ","usage":"thể hiện sự biến đổi theo 1 chiều, xu hướng (tăng lên, xấu đi), trong đó ばかり là theo xu hướng xấu","examples":[{"jp":"{一度|いちど}{問題|もんだい}が{起|お}きてたら、{彼|かれ}と{人間|にんげん}{関係|かんけい}は{悪|わる}くなる{一方|いっぽう}だ","vi":"Sau một lần có vấn đề xảy ra, mối quan hệ của mọi người với anh ấy xấu dần đi."},{"jp":"{東京|とうきょう}の{交通|こうつう}{機関|きかん}が{複雑|ふくざつ}になるばかりで、わたしはよくわからなくなってきた","vi":"Giao thông ở Tokyo ngày càng phức tạp, tôi cũng trở nên không hiểu rõ nữa."}]},
      {"no":3,"patterns":["～としている"],"meaning":"Sắp sửa…, đang định…","structure":"V ý hướng （よう）＋としている","usage":"sắp sửa có sự kiện xảy ra, kết thúc","examples":[{"jp":"{決勝戦|けっしょうせん}が{今|いま}{始|はじ}まろうとしています。みんな{緊張|きんちょう}しています。","vi":"Trận chung kết sắp bắt đầu bây giờ. Mọi người đều đang căng thẳng."}]},
      {"no":4,"patterns":["～つつある"],"meaning":"Đang dần…, đang trong quá trình…","structure":"V ~~ます~~＋つつある","usage":"Đang trong quá trình một sự vật, hiện tượng biến đổi. Ấn tượng đối với người nói thì nhẹ hơn so với ばかりだ/一方だ。","examples":[{"jp":"この{会社|かいしゃ}は{現在|げんざい}{発展|はってん}しつつあり、{将来|しょうらい}が{期待|きたい}される","vi":"Công ty này hiện tại vẫn đang phát triển, tương lai được kì vọng."}]},
      {"no":5,"patterns":["～つつ"],"meaning":"Vừa… vừa… (văn viết)","structure":"V~~ます~~＋つつ","usage":"Vừa thực hiện hành động này, vừa thực hiện hành động kia. Mẫu này có ý nghĩa giống với ながら nhưng là cách nói cứng hơn","examples":[{"jp":"あの{空|あ}き{地|ち}をどうするかについては、{住民|じゅうみん}と{話|はな}し{合|あ}いつつ、{計画|けいかく}を{立|た}てていきたい","vi":"Về việc sẽ sử dụng khu đất trống đó như thế nào, tôi muốn vừa thảo luận với người dân, vừa lên kế hoạch."}]},
      {"no":6,"patterns":["～うちに"],"meaning":"Trong khi còn… / Trong lúc… thì (thay đổi)","structure":"①N, A {普通|ふつう}＋うちに\n②V る/ている/ない＋うちに","usage":"① trong lúc này làm tốt hơn là để sau\n② trong lúc làm A thì B thay đổi, trong lúc (thời gian ngắn) đang làm gì thì có sự biến đổi trạng thái","examples":[{"jp":"{忘|わす}れないうちに、カレンダーでメモしておく。","vi":"trong khi mà chưa quên , thì hãy viết ghi chú vào trong lịch."},{"jp":"{知|し}らないうちに、{雨|あめ}が{降|ふ}り{始|はじ}め{出|だ}した。","vi":"Trong lúc không biết thì mưa đã bắt đầu rơi"}]}
